def is_valid_pdf(file_path):
    try:
        with open(file_path, 'rb') as f:
            header = f.read(4)
            return header == b'%PDF'
    except Exception:
        return False

# Example usage
file_path = 'example.pdf'
print(is_valid_pdf(file_path))  # Should print True if the file is a valid PDF
